head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
// onbeforeselect 에서 false 를 반환해 선택 변경을 취소한다
scwin.target1_onbeforeselect = function (selectedIndex, index) {
    scwin.setReturnValue("=====target1_onbeforeselect===== (false 반환 : 선택 변경 취소)");
    scwin.setReturnValue("selectedIndex : " + selectedIndex + " / index : " + index);
    return false;
};

scwin.target1_onchange = function (e) {
    scwin.setReturnValue("=====target1_onchange=====");
};

// 선택 상태를 API 값과 화면 상태 양쪽으로 출력
scwin.btn_getState_onclick = function (e) {
    var objComp = $p.getComponentById("target1");
    var arrRadio = objComp.render.querySelectorAll("input[type='radio']");
    var arrChecked = [];

    for (var i = 0; i < arrRadio.length; i++) {
        if (arrRadio[i].checked) {
            arrChecked.push(i);
        }
    }

    scwin.setReturnValue("[선택 상태] getSelectedIndex() : " + objComp.getSelectedIndex()
        + " / getValue() : '" + objComp.getValue() + "'"
        + " / 화면에서 선택 표시된 아이템 : [" + arrChecked.join(", ") + "]");
};
